import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1788348328000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is configured through environment variables. There is no config file and no command-line flag.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>AUDIOBOOKSHELF_URL</code></td><td>yes</td><td>—</td><td>Base URL of the instance, e.g. <code>https://abs.example.com</code></td></tr><tr><td><code>AUDIOBOOKSHELF_API_KEY</code></td><td>yes</td><td>—</td><td>API key, sent as <code>Authorization: Bearer …</code></td></tr><tr><td><code>AUDIOBOOKSHELF_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the 29 read tools</td></tr><tr><td><code>AUDIOBOOKSHELF_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td><code>true</code> accepts self-signed certificates for this connection</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token</td></tr></tbody></table><p>Only the exact string <code>true</code> enables the two <code>AUDIOBOOKSHELF_*</code> booleans. <code>1</code>, <code>yes</code> and <code>TRUE</code> do not — which is worth knowing, because a typo in <code>AUDIOBOOKSHELF_READ_ONLY</code> fails <em>open</em>, with the write tools registered. The server logs which switches are active at startup; check that line rather than trusting the spelling.</p><p><code>ELICITATION</code> is the exception in both directions: it is case-insensitive, and a value that is neither <code>true</code> nor <code>false</code> <strong>stops the server</strong> instead of falling back. It is the only one here that defaults to <em>on</em>, so failing open on a typo would leave the dialog running while you believed it was off. It also carries no prefix, which means it reaches every MCP server in the same environment — see <a href="/guide/approval">Asking a person</a>.</p><p>See the <a href="/reference/environment">environment reference</a> for the same table with the validation rules.</p><h2 id="audiobookshelf-url" tabindex="-1"><code>AUDIOBOOKSHELF_URL</code> <a class="header-anchor" href="#audiobookshelf-url" aria-label="Permalink to “AUDIOBOOKSHELF_URL”">​</a></h2><p>Validated at startup with <code>new URL()</code>. The server <strong>exits</strong> if it is:</p><ul><li>unparseable,</li><li>not <code>http://</code> or <code>https://</code>,</li><li>or carries credentials in the form <code>https://user:pass@host</code> — those would end up in logs and error messages, and the API key is the supported mechanism.</li></ul><p>Trailing slashes are stripped, so <code>https://abs.example.com/</code> and <code>https://abs.example.com</code> behave identically.</p><p>Plain <code>http://</code> to a <strong>non-loopback</strong> host produces a warning and keeps going: the API key would cross the network unencrypted. <code>http://localhost</code> and <code>http://127.*</code> do not warn.</p><div class="tip custom-block"><p class="custom-block-title">Reverse proxies and subpaths</p><p>Point the URL at whatever serves the Audiobookshelf UI. If it lives under a subpath, include it — <code>https://media.example.com/audiobookshelf</code>. The server appends <code>/api/…</code> to exactly what you give it.</p></div><h2 id="audiobookshelf-api-key" tabindex="-1"><code>AUDIOBOOKSHELF_API_KEY</code> <a class="header-anchor" href="#audiobookshelf-api-key" aria-label="Permalink to “AUDIOBOOKSHELF_API_KEY”">​</a></h2><p>Created under <strong>Settings → Users → API Keys</strong> by an admin, shown once.</p><p>The key is <strong>deleted from <code>process.env</code> once the configuration has been read</strong>, so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code> for the lifetime of the process.</p><p>Credentials are only required when a tool actually calls the API — not at startup. The server starts, handshakes and lists its tools without them, and every call then fails with the setup instructions. That is what lets a registry sandbox enumerate the tools.</p><h2 id="audiobookshelf-read-only" tabindex="-1"><code>AUDIOBOOKSHELF_READ_ONLY</code> <a class="header-anchor" href="#audiobookshelf-read-only" aria-label="Permalink to “AUDIOBOOKSHELF_READ_ONLY”">​</a></h2><p><code>true</code> means the 15 write tools are <strong>never registered</strong> — not registered and then refused. A client asking for <code>tools/list</code> sees 29 tools, and there is no capability advertised that the server would decline to provide.</p><p>Use it when you want the library answerable but not editable, which is most of the time.</p><h2 id="audiobookshelf-insecure-tls" tabindex="-1"><code>AUDIOBOOKSHELF_INSECURE_TLS</code> <a class="header-anchor" href="#audiobookshelf-insecure-tls" aria-label="Permalink to “AUDIOBOOKSHELF_INSECURE_TLS”">​</a></h2><p>For an instance behind a self-signed or internal-CA certificate.</p><p>This does <strong>not</strong> set <code>NODE_TLS_REJECT_UNAUTHORIZED</code>. It creates a scoped <a href="https://undici.nodejs.org/" target="_blank" rel="noreferrer">undici</a> dispatcher used only for requests to your Audiobookshelf, so nothing else the process does is affected. The server prints a warning to stderr while it is on.</p><p>Prefer adding your CA to the system trust store; this switch is the escape hatch, not the recommendation.</p><h2 id="fixed-behaviour" tabindex="-1">Fixed behaviour <a class="header-anchor" href="#fixed-behaviour" aria-label="Permalink to “Fixed behaviour”">​</a></h2><p>Not configurable, deliberately:</p><table tabindex="0"><thead><tr><th>Behaviour</th><th>Value</th><th>Why</th></tr></thead><tbody><tr><td>Request timeout</td><td>15 s</td><td>A hung request would hang the tool call</td></tr><tr><td>Redirects</td><td>never followed</td><td>A redirect would replay the <code>Authorization</code> header at another host</td></tr><tr><td>Response ceiling</td><td>5 MB</td><td><code>/api/collections</code> does not paginate and embeds every book</td></tr><tr><td>Result ceiling</td><td>100 000 bytes</td><td>One call must not be able to flood the context</td></tr><tr><td>Item-page cap</td><td>100 entries</td><td><code>list_library_items</code> only; the API pages that route</td></tr><tr><td>Embedded members</td><td>first 25</td><td>A compact collection or playlist reports the count, not the whole list</td></tr><tr><td>Description cap</td><td>800 characters</td><td>Metadata-provider descriptions run to many kB</td></tr><tr><td>Error body cap</td><td>2000 chars</td><td>HTML error pages are dropped entirely, other bodies truncated</td></tr><tr><td>Confirm-token TTL</td><td>5 minutes</td><td>Long enough for a round trip, short enough not to linger</td></tr></tbody></table><h2 id="choosing-the-tools-that-load" tabindex="-1">Choosing the tools that load <a class="header-anchor" href="#choosing-the-tools-that-load" aria-label="Permalink to “Choosing the tools that load”">​</a></h2><p>Read-only mode is one cut, along a line this server drew for you. <code>AUDIOBOOKSHELF_ALLOW_TOOLS</code> and <code>AUDIOBOOKSHELF_DENY_TOOLS</code> let you draw your own:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">AUDIOBOOKSHELF_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">AUDIOBOOKSHELF_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">search_library,get_library_item,set_media_progress</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">AUDIOBOOKSHELF_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">delete_*</span></span></code></pre></div><p>Why bother, when all forty-four work: a model chooses the right tool far more reliably from a handful than from a long list, and every tool it can see costs context on every single request. If this is the only MCP server in a session, forty-four is fine. If it is one of six, it is not.</p><p><strong>The syntax.</strong> Comma-separated entries. An entry is either an exact tool name or a prefix with a trailing <code>*</code> — <code>list_*</code> matches every tool whose name starts with <code>list_</code>. Entries are trimmed and case-insensitive, empty ones are ignored, and an empty value counts as unset. Nothing else is a pattern: <code>*_x</code> and <code>list_*_x</code> are rejected rather than silently matching nothing.</p><p><strong><code>essential</code></strong> is a curated preset of eight:</p><p><code>list_libraries</code>, <code>search_library</code>, <code>list_library_items</code>, <code>get_library_item</code>, <code>get_item_chapters</code>, <code>list_items_in_progress</code>, <code>get_media_progress</code>, <code>set_media_progress</code>.</p><p>It composes — naming a tool alongside it puts that one back, and <code>AUDIOBOOKSHELF_DENY_TOOLS</code> takes one away.</p><p><strong>Both together.</strong> <code>AUDIOBOOKSHELF_ALLOW_TOOLS</code> decides what is in; <code>AUDIOBOOKSHELF_DENY_TOOLS</code> is then subtracted from the result. With only a deny list, everything else stays.</p><p><strong>A name that matches nothing stops the server</strong>, with the offending entry and the list of real names. That is deliberate: the alternative is a tool quietly missing from <code>tools/list</code>, and nobody traces an absence back to an environment variable. The same applies to a pattern that matches no tool.</p><p><strong>With read-only mode</strong>, the write tools are not registered at all, so naming one explicitly in <code>AUDIOBOOKSHELF_ALLOW_TOOLS</code> is an error that says so — rather than calling a tool unknown when it plainly exists. A <em>pattern</em> that covers write tools is fine and simply contributes nothing, and <code>AUDIOBOOKSHELF_ALLOW_TOOLS=essential</code> narrows to the read half of the preset.</p><div class="tip custom-block"><p class="custom-block-title">It is the same cut, not a second one</p><p>A filtered tool is never registered, so it is absent from <code>tools/list</code> and unknown to <code>tools/call</code> alike — exactly what <code>AUDIOBOOKSHELF_READ_ONLY</code> does to a write tool. There is no &quot;hidden but callable&quot; state to reason about.</p></div>`,38)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};